//
// A check that always passes is indistinguishable from a working one
// until something breaks in production. This is what tells them apart:
// give each check a ProvenBy, and this proves the check can fail.
//
// A check with no ProvenBy is not ignored — it has to say why, in
// Argued. The two are held level in both directions: claiming proof
// without a broken implementation fails here, and supplying one for a
// check that claims nothing fails too.
func ProveContract(
	t *testing.T, checks ContractChecks,
) {
	t.Helper()
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := contractNewFixture()
	bound := make([]suite.Check[Contract], 0, len(checks))
	defects := prove.Defects[Contract]{}
	for _, row := range checks {
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveContract: %v", err)
		}
		bound = append(bound, bd)
		if row.ProvenBy == nil {
			continue
		}
		sub, err := row.ProvenBy.Subject()
		if err != nil {
			t.Fatalf("ProveContract: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[Contract]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	prove.All(t, bound, defects)
}

// contractModelRows is what this package's model tier claims.
//
// Every row here needs sequences of calls judged against something
// outside the subject, which is what separates them from the rows
// above: those settle a claim with a fixed call sequence, and these
// cannot be stated that way at all. That is also why each takes the
// Subject rather than an instance — a sequence run builds its own, and
// some of them build two.
func contractModelRows() []suite.Check[Contract] {
	return []suite.Check[Contract]{
		{
			ID:          contractCheckIndex.Model.Laws(),
			Class:       suite.ClassLaws,
			Claim:       "every bound law holds over random operation sequences",
			Falsifiable: suite.Argued("no mechanical rule plants a defect for this claim; the ones that would are domain composites, which no rule reaches from shape and stamps alone"),
			Strength:    suite.StrengthDifferential,
			RunWith: func(tb testing.TB, sub suite.Subject[Contract]) {
				contractAssertLaws(tb, sub)
			},
		},
		{
			ID:    contractCheckIndex.Model.CloseIdempotent(),
			Class: suite.ClassLifecycle,
			Claim: "a second Close on a cursor changes nothing",
			Binds: []string{
				lawid.CursorCloseIdempotent,
			},
			Falsifiable: suite.Argued("no mechanical rule plants a defect for this claim; the ones that would are domain composites, which no rule reaches from shape and stamps alone"),
			Strength:    suite.StrengthDifferential,
			RunWith: func(tb testing.TB, sub suite.Subject[Contract]) {
				contractAssertCloseIdempotent(tb, sub)
			},
		},
	}
}

// --- Contract's model tier -------------------------------------------
//
// Random sequences of Contract's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and ContractSuite.Without declines any of them by name.
//
//	Reference: the subject's own factory — no reader/writer pair derives a store,
//	           so a second instance driven identically stands in: twins must
//	           agree, which catches nondeterminism and hidden shared state but
//	           not a subject wrong the same way twice; ref= raises the floor
//	Sequences: Next (multiaggregator), Close (lifecycle)
//	Laws:      AUTO-LIFECYCLE-RESPECTS-CONTEXT
//	Not bound:
//	           AUTO-COUNT-EQUALS-REFERENCE — observes through Next, which answers several results no single-valued closure returns
//	           AUTO-CURSOR-NEXT-AFTER-CLOSE — lawid: claim "once a {produced} is closed, {next} reports the closed sentinel" left {next} unfilled
//
// contractModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func contractModelActions() []model.Action[Contract] {
	return []model.Action[Contract]{
		action.MultiAggregator("Next",
			func(ctx context.Context, s cursor.Contract) (cursor.Value, bool, error) {
				return s.Next(ctx)
			}),
		action.Lifecycle("Close",
			func(ctx context.Context, s cursor.Contract) error {
				return s.Close(ctx)
			}),
	}
}

// contractModelLaws is the laws the classifications earned and this build
// could fill.
//
// Observational, every one of them: a law never mutates, so running them
// inside the sequences is safe for every step that follows. What they
// judge is the subject's own behaviour, which is why they are a separate
// leg from the reference comparison rather than more oracles on it.
func contractModelLaws() []law.Law[Contract] {
	return []law.Law[Contract]{
		law.LifecycleRespectsContext[cursor.Contract]{
			Op: func(ctx context.Context, s cursor.Contract) error {
				return s.Close(ctx)
			},
		},
	}
}

// contractAssertLaws drives the same sequences with the bound laws as the only
// oracle, and reports when they engaged nothing.
//
// The differential verdict is off here, and that is the whole reason this
// is a second leg rather than more options on the first: with it armed, a
// subject broken anywhere disagrees at step 0 and no law is ever reached,
// which makes "can this law catch a defect" unanswerable.
//
// The report is the other half. A law behind a precondition the subject
// refuses on every draw passes every time and asserts nothing, and from
// outside that is indistinguishable from a law that held.
func contractAssertLaws(
	tb testing.TB,
	sub suite.Subject[Contract],
) {
	tb.Helper()

	// The run's declared oracle where one exists, the derived reference
	// otherwise — and the report says which, because a law held against a
	// second copy of the subject is a weaker claim than the same law held
	// against something written independently.
	buildRef, tier := legs.Reference(tb, sub, func() Contract { return sub.New(tb) })
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Contract { return sub.New(tb) }, buildRef,
		contractModelActions(),
		contractModelLaws())
}

// contractAssertCloseIdempotent binds AUTO-CURSOR-CLOSE-IDEMPOTENT over the shared sequences.
//
// One law, and the run's only oracle. The differential is off here, as
// on every law leg: with it armed a subject broken anywhere disagrees at
// step 0, and whether THIS law can catch a defect stays unanswerable.
func contractAssertCloseIdempotent(
	tb testing.TB,
	sub suite.Subject[Contract],
) {
	tb.Helper()

	buildRef, tier := legs.Reference(tb, sub, func() Contract { return sub.New(tb) })
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Contract { return sub.New(tb) }, buildRef,
		contractModelActions(),
		[]law.Law[Contract]{
			law.CursorCloseIdempotent[cursor.Contract]{
				Close: func(rt *model.T, s cursor.Contract) error {
					return s.Close(rt.Context())
				},
			},
		})
}

// ContractSatWear is one wearable defect: a kind, and the wrap that
// dresses a subject in it.
type contractSatWear struct {
	kind string
	wrap func(fx ContractFixture, s cursor.Contract) cursor.Contract
}

//nolint:gochecknoglobals // the prover's wardrobe, read-only after init.
var contractSatWears = map[string][]contractSatWear{}

//nolint:gochecknoinits // the wardrobe fills once, keyed by method.
func init() { //nolint:staticcheck // an empty wardrobe leaves dress unused by design.
	dress := func(method, kind string, wrap func(fx ContractFixture, s cursor.Contract) cursor.Contract) {
		contractSatWears[method] = append(contractSatWears[method],
			contractSatWear{kind: kind, wrap: wrap})
	}
	dress("Close", "inert", func(_ ContractFixture, s cursor.Contract) cursor.Contract {
		return contractSatInertClose{s}
	})
	dress("Close", "flicker", func(_ ContractFixture, s cursor.Contract) cursor.Contract {
		return &contractSatFlickerClose{Contract: s}
	})
	dress("Close", "sputter", func(_ ContractFixture, s cursor.Contract) cursor.Contract {
		return &contractSatSputterClose{Contract: s}
	})
	dress("Close", "stick", func(_ ContractFixture, s cursor.Contract) cursor.Contract {
		return &contractSatStickClose{Contract: s}
	})
	dress("Close", "latch", func(_ ContractFixture, s cursor.Contract) cursor.Contract {
		return &contractSatLatchClose{Contract: s}
	})
	dress("Next", "inert", func(_ ContractFixture, s cursor.Contract) cursor.Contract {
		return contractSatInertNext{s}
	})
	dress("Next", "flicker", func(_ ContractFixture, s cursor.Contract) cursor.Contract {
		return &contractSatFlickerNext{Contract: s}
	})
	dress("Next", "sputter", func(_ ContractFixture, s cursor.Contract) cursor.Contract {
		return &contractSatSputterNext{Contract: s}
	})
}

// contractSatOnly narrows the bound set to one law.
//
// The prover's instrument, not a knob. A conformance run asserts every
// law the classifications earned; dropping all but one is only ever
// right when the question is "can THIS law fail", which is the one
// question asked here.
func contractSatOnly(laws []law.Law[Contract], id string) (law.Law[Contract], bool) {
	for _, l := range laws {
		if l.ID() == id {
			return l, true
		}
	}
	return nil, false
}

// ContractModelSaturation proves the bound laws can fail.
//
// Binding a law is necessary; this is what makes it sufficient. Per law,
// a defect is worn on each method the law's closures reach — zeros, the
// fixture pair alternated, a waning count — and at least one worn run
// must fail naming the law's own identifier. A law every defect survives
// is bound but unsaturatable, and fails here by name.
//
// It takes YOUR implementation, because that is the only correct subject
// there is to break: a defect worn over the generated double proves
// nothing, since the double answers zeros before anything is worn on it.
//
//	func TestMyLawsCanFail(t *testing.T) {
//		ContractModelSaturation(t, func() Contract { return NewMine() })
//	}
func ContractModelSaturation(t *testing.T, factory func() Contract) {
	t.Helper()
	fx := DefaultContractFixture()
	_ = fx
	t.Run("AUTO-CURSOR-NEXT-AFTER-CLOSE", func(t *testing.T) {
		// Not a survival, and the distinction is the whole point of the
		// defect-class axis. This law's name promises a defect the wardrobe
		// cannot produce — every dressing here acts on what a call answers,
		// and a partial effect or a retained resource is not an answer. The
		// gap is in the wardrobe, and conformance/gate.UnprovableLaws is where
		// it is argued and counted.
		t.Skip("no wear produces the defect AUTO-CURSOR-NEXT-AFTER-CLOSE is named for; the wardrobe owes it one")
	})
	t.Run("AUTO-CURSOR-CLOSE-IDEMPOTENT", func(t *testing.T) {
		one, bound := contractSatOnly(contractModelLaws(), "AUTO-CURSOR-CLOSE-IDEMPOTENT")
		if !bound {
			t.Skip("the law was selected and this build did not register it; the header says what it is waiting on")
		}
		proving := map[string]bool{"stick": true}
		killed := func() bool {
			for _, method := range []string{"Close"} {
				for _, wear := range contractSatWears[method] {
					if !proving[wear.kind] {
						continue
					}
					// Two references per defect. Silencing the differential leaves
					// the law as the only witness, but not every action reports
					// through it: a shape whose action fails structurally still
					// ends the iteration, and a reference wearing the same defect
					// behaves the same way the subject does, so nothing diverges
					// and the law is reached. A law that *is* the comparison needs
					// the opposite — with both sides worn it has nothing to
					// disagree with — so the clean reference runs too and either
					// kill counts. The corpus measured both: dropping either one
					// loses laws that only the other can saturate.
					for _, blind := range []bool{true, false} {
						surrogate := "ContractSat_AUTO-CURSOR-CLOSE-IDEMPOTENT_" + method + "_" + wear.kind
						if blind {
							surrogate += "_blind"
						}
						t.Cleanup(func() {
							_ = os.RemoveAll(filepath.Join("testdata", "rapid", surrogate))
							_ = os.Remove(filepath.Join(
								model.ResolveArtifactDir(""), "failure-"+surrogate+".json"))
						})
						reference := factory
						if blind {
							reference = func() Contract { return wear.wrap(fx, factory()) }
						}
						f := testkit.NewFailableTB().WithName(surrogate)
						// One law and no differential: with siblings registered the
						// first to catch a defect ends the iteration, and every
						// other law bound on the same methods reads as
						// unsaturatable. Isolating it is what leaves this law as
						// the only witness.
						model.Assert(f,
							func() Contract { return wear.wrap(fx, factory()) },
							model.WithReference(reference),
							model.WithActions(contractModelActions()...),
							model.WithLawsOnly[Contract](true),
							model.WithLaw(one))
						// The reporter's own rendering, not the bare identifier.
						// rapid echoes the TB's name into its final message and the
						// surrogate above is named for this law, so matching the
						// identifier alone matched the name — the criterion reduced
						// to f.Failed() and every defect "killed" every law. The
						// verdict's format carries the identifier where no name can:
						// after the kind, which is the one place only the reporter
						// writes. The suffix rather than the whole prefix because a
						// REQ-tagged law renders "[REQ-1 invariant]".
						if f.Failed() && (strings.Contains(f.Msg(), "invariant] AUTO-CURSOR-CLOSE-IDEMPOTENT")) {
							return true
						}
					}
				}
			}
			return false
		}()
		if !killed {
			t.Errorf("AUTO-CURSOR-CLOSE-IDEMPOTENT survived every defect worn on its own methods — bound but unsaturatable")
		}
		// Not yet narrowed to this law's own defect class. The wears whose
		// class its name claims are
		// stick — requiring the kill to come from one
		// of those reddens 23 laws across the corpus, and the measurement says
		// roughly a third are weak laws and the rest are wrong classes. That
		// triage is 1.10b. What ships here is the skip above, which is the
		// half the measurement settled.
	})
	t.Run("AUTO-LIFECYCLE-RESPECTS-CONTEXT", func(t *testing.T) {
		// Not a survival, and the distinction is the whole point of the
		// defect-class axis. This law's name promises a defect the wardrobe
		// cannot produce — every dressing here acts on what a call answers,
		// and a partial effect or a retained resource is not an answer. The
		// gap is in the wardrobe, and conformance/gate.UnprovableLaws is where
		// it is argued and counted.
		t.Skip("no wear produces the defect AUTO-LIFECYCLE-RESPECTS-CONTEXT is named for; the wardrobe owes it one")
	})
}

// contractSatInertClose answers zeros where Close should act.
type contractSatInertClose struct{ cursor.Contract }

func (contractSatInertClose) Close(_ context.Context) (z0 error) {
	return
}

// contractSatFlickerClose answers zeros every second
// call, where Close should answer the same thing twice.
//
// The defect every stability claim names: cacheable, deterministic,
// consistent, non-decreasing are all about two calls agreeing, and a subject
// that answers zeros *forever* agrees with itself perfectly. Only an answer
// that changes breaks them, and alternating with the zero is the smallest
// change available at any return type.
type contractSatFlickerClose struct {
	cursor.Contract
	flip atomic.Int64
}

func (m *contractSatFlickerClose) Close(p0 context.Context) (z0 error) {
	if m.flip.Add(1)%2 == 0 {
		return
	}
	return m.Contract.Close(p0)
}

// contractSatSputterClose alternates a minted refusal
// with the real answer where Close should be steady.
type contractSatSputterClose struct {
	cursor.Contract
	flip atomic.Int64
}

func (m *contractSatSputterClose) Close(p0 context.Context) (z0 error) {
	if m.flip.Add(1)%2 == 1 {
		z0 = errors.New("contract: saturation sputtered a refusal")
		return
	}
	return m.Contract.Close(p0)
}

// contractSatStickClose lets Close work once
// and refuses forever after — the close that is not idempotent.
//
// sputter cannot express this. An idempotence law calls twice and discards
// the first answer, so an alternating refusal is absorbed by the very call
// the law is not reading, on every iteration. What the claim forbids is the
// *second* call failing, and only a defect that arrives after the first can
// say so.
type contractSatStickClose struct {
	cursor.Contract
	used atomic.Bool
}

func (m *contractSatStickClose) Close(p0 context.Context) error {
	if m.used.Swap(true) {
		return errors.New("contract: saturation stuck Close after its first call")
	}
	return m.Contract.Close(p0)
}

// contractSatLatchClose lets the first
// Close through and quietly drops every one after it.
//
// The order-sensitive fold, which is the one defect a commutativity claim can
// see. That law builds both its instances from the same worn factory and
// applies the same values in opposite orders, so every other wear reaches
// both sides identically and the two observations agree however wrong they
// are. A fold that keeps only what it saw first keeps a different thing on
// each side.
//
// Silent, where stick refuses: a claim about what an operation *did* cannot
// be broken by one that says it failed.
type contractSatLatchClose struct {
	cursor.Contract
	used atomic.Bool
}

func (m *contractSatLatchClose) Close(p0 context.Context) error {
	if m.used.Swap(true) {
		return nil
	}
	return m.Contract.Close(p0)
}

